async function loadCronStatus(){const requestId=++cronUi.statusSequence;try{const cron=await api('${CRON_CONFIG.apiRoutes.status}');if(requestId!==cronUi.statusSequence||cronUi.saving)return;const element=$('#cronStatus'),details=$('#cronDetails'),runButton=$('#runCronNow');state.cronEnabled=cron.enabled!==false;const enabledDomainCount=Number(cron.enabledDomainCount)||0,totalDomainCount=Number(cron.totalDomainCount)||0,toggle=$('#cronEnabled');if(toggle)toggle.checked=state.cronEnabled;if(runButton){runButton.disabled=!state.cronEnabled||cron.running||enabledDomainCount===0;runButton.title=enabledDomainCount===0?'请先在域名配置中开启自动优选同步':'';runButton.textContent=cron.running?'任务运行中':enabledDomainCount===0?'没有启用域名':'立即执行一次';}const last=cron.lastResult,lastAt=last?.at?new Date(last.at).toLocaleString():'尚未执行',changes=last?.dnsChanges;const dnsText=changes?' · DNS 新增 '+changes.created+'、更新 '+changes.updated+'、删除 '+changes.deleted+'、保留 '+changes.kept:'';const alarmAt=typeof cron.nextAlarm==='number'&&Number.isFinite(cron.nextAlarm)?new Date(cron.nextAlarm):null,nextText=alarmAt&&!Number.isNaN(alarmAt.getTime())?alarmAt.toLocaleString([], {month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):state.cronEnabled&&enabledDomainCount?'按 Worker Cron 计划（每 ${CRON_CONFIG.intervalLabel}）':'未安排';if(details){if(!state.cronEnabled)details.innerHTML='<span class="summary-dot warning"></span><span><strong>定时任务已关闭</strong><small>手动检测和同步仍可正常使用</small></span>';else if(enabledDomainCount===0)details.innerHTML='<span class="summary-dot warning"></span><span><strong>没有域名参与自动同步</strong><small>请在域名配置中为需要定时更新的域名开启“自动优选同步”</small></span>';else if(cron.running)details.innerHTML='<span class="summary-dot ok"></span><span><strong>正在检测 '+cron.checkedCount+'/'+cron.total+' 个候选</strong><small>当前可用 '+cron.reachableCount+' 个 · 完成后只同步 '+enabledDomainCount+' 个已启用域名</small></span>';else details.innerHTML='<span class="summary-dot '+(last?.ok?'ok':last?'warning':'')+'"></span><span><strong>'+(last?.ok?'上次自动同步成功':last?'上次任务失败':'等待首次执行')+'</strong><small>自动同步域名：'+enabledDomainCount+'/'+totalDomainCount+' · 上次：'+lastAt+' · 下次计划：'+nextText+(last?.ok?dnsText:last&&!last.ok?' · '+esc(last.error||'未知错误'):'')+'</small></span>';}if(!element)return;if(!state.cronEnabled){element.textContent='定时任务：已关闭';element.className='status warning';return;}if(enabledDomainCount===0){element.textContent='定时任务：等待启用域名';element.className='status warning';return;}if(cron.running){element.textContent='定时检测中：'+cron.checkedCount+'/'+cron.total+' · 可用 '+cron.reachableCount+' 个 · 同步 '+enabledDomainCount+' 个域名';element.className='status loading';return;}if(!last){element.textContent='定时任务：每 ${CRON_CONFIG.intervalLabel} · 自动同步 '+enabledDomainCount+'/'+totalDomainCount+' 个域名';element.className='status';return;}element.textContent=last.ok?'上次定时同步成功：检测 '+last.checkedCount+' 个，可用 '+last.reachableCount+' 个 · 同步 '+enabledDomainCount+'/'+totalDomainCount+' 个域名':'上次定时任务失败：'+(last.error||'未知错误');element.className='status '+(last.ok?'ok':'err');}catch{}}
async function saveCronConfig(enabled=$('#cronEnabled').checked){if(cronUi.saving)return;const toggle=$('#cronEnabled'),previous=state.cronEnabled!==false;cronUi.saving=true;cronUi.statusSequence++;toggle.disabled=true;try{setStatus($('#cronConfigStatus'),'保存中…');const result=await api('${CRON_CONFIG.apiRoutes.config}',{method:'PUT',body:JSON.stringify({enabled})});state.cronEnabled=result.cronEnabled!==false;toggle.checked=state.cronEnabled;setStatus($('#cronConfigStatus'),state.cronEnabled?'定时任务已启用':'定时任务已关闭');notify(state.cronEnabled?'定时优选同步已启用':'定时优选同步已关闭');}catch(error){state.cronEnabled=previous;toggle.checked=previous;const message=error instanceof Error?error.message:String(error);setStatus($('#cronConfigStatus'),message,true);notify(message,'error');}finally{cronUi.saving=false;toggle.disabled=false;await loadCronStatus();}}
async function runCronNow(){setBusy('#runCronNow',true);try{setStatus($('#cronConfigStatus'),'正在启动定时任务…');const result=await api('${CRON_CONFIG.apiRoutes.run}',{method:'POST',body:'{}'});const blocked=result.reason==='disabled'||result.reason==='no-enabled-domains';const message=result.started?'定时检测已启动':result.reason==='already-running'?'定时任务已在运行':result.reason==='disabled'?'请先启用定时任务':result.reason==='no-enabled-domains'?'请先为至少一个域名开启自动优选同步':'当前未启动任务';setStatus($('#cronConfigStatus'),message,blocked);notify(message,blocked?'error':'success');}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#cronConfigStatus'),message,true);notify(message,'error');}finally{setBusy('#runCronNow',false);await loadCronStatus();}}
function currentValidatedSources(requireEnabled=false){readConfig();const urls=state.ipSources.map(source=>source.url.toLowerCase()),duplicate=urls.find((url,index)=>url&&urls.indexOf(url)!==index);if(duplicate)throw Error('IP 来源 URL 不能重复：'+duplicate);const invalid=state.ipSources.find(source=>{try{const parsed=new URL(source.url);return !['http:','https:'].includes(parsed.protocol)||!parsed.hostname;}catch{return true;}});if(invalid)throw Error('IP 来源 URL 无效：'+invalid.url);if(requireEnabled&&!state.ipSources.some(source=>source.enabled))throw Error('请至少启用一个 IP 来源');return state.ipSources;}
function updateRegionSelectionMeta(){const options=[...document.querySelectorAll('.preferred-region')],meta=$('#regionSelectionMeta');if(meta)meta.textContent='已选 '+options.filter(input=>input.checked).length+'/'+options.length+' 个地区'+(regionSelectionChanged()?' · 未保存':'');updateRegionActionState();}
async function discoverRegions(){if(regionDiscoveryBusy||regionSaveBusy||sourceBusy)return;regionDiscoveryBusy=true;updateRegionActionState();try{setStatus($('#sourceStatus'),'正在获取并保存地区目录…');const sources=currentValidatedSources(true);const result=await api('/api/ips/regions',{method:'POST',body:JSON.stringify({ipSources:sources})});renderRegionFilters(result.availableRegions||[],true,result.regionCounts||{},result.untaggedCount,result.fetchedAt);const failed=(result.sources||[]).filter(source=>source.error),message=result.availableRegions?.length?'地区目录已持久化：'+result.availableRegions.length+' 个地区、'+(result.sourceTotal||0)+' 个 443 IP'+(failed.length?'，'+failed.length+' 个来源失败':''):'API 中没有可识别的地区标签';setStatus($('#sourceStatus'),message,!result.availableRegions?.length);notify(message,result.availableRegions?.length?'success':'error');}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#sourceStatus'),message,true);notify(message,'error');}finally{regionDiscoveryBusy=false;updateRegionActionState();}}
async function loadRegionCatalog(){try{const catalog=await api('/api/ips/regions');if(catalog.available)renderRegionFilters(catalog.availableRegions||[],true,catalog.regionCounts||{},catalog.untaggedCount,catalog.fetchedAt);else if(Array.isArray(savedPreferredRegions))renderRegionFilters(savedPreferredRegions,true,{},0);}catch{if(Array.isArray(savedPreferredRegions))renderRegionFilters(savedPreferredRegions,true,{},0);}}
async function saveRegionConfig(){if(regionDiscoveryBusy||regionSaveBusy||sourceBusy)return;readRegionConfig();if(!regionSelectionChanged())return;regionSaveBusy=true;updateRegionActionState();try{setStatus($('#sourceStatus'),'正在保存地区配置…');const result=await api('/api/ips/regions/config',{method:'PUT',body:JSON.stringify({preferredRegions:state.preferredRegions})});state.preferredRegions=Array.isArray(result.preferredRegions)?result.preferredRegions:null;savedPreferredRegions=normalizeRegionSelection(state.preferredRegions);renderRegionFilters(availableRegions,true,regionCounts,untaggedRegionCount,regionCatalogFetchedAt);setPreferredSnapshot({available:false});const message=state.preferredRegions===null?'地区配置已保存：不限制地区':'地区配置已保存：'+(state.preferredRegions.join('、')||'仅保留未标注地区 IP');setStatus($('#sourceStatus'),message);notify(message);}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#sourceStatus'),message,true);notify(message,'error');}finally{regionSaveBusy=false;updateRegionActionState();}}
async function saveSourcesAndFetch(){if(sourceBusy||regionDiscoveryBusy||regionSaveBusy||regionSelectionChanged())return;sourceBusy=true;updateRegionActionState();try{setStatus($('#sourceStatus'),'保存来源中…');const sources=currentValidatedSources();Object.assign(state,await api('/api/ip-sources',{method:'PUT',body:JSON.stringify({ipSources:sources})}));savedPreferredRegions=normalizeRegionSelection(state.preferredRegions);renderConfig();const result=await api('/api/ips/collect',{method:'POST',body:'{}'});regionCatalogFetchedAt=result.catalogFetchedAt||regionCatalogFetchedAt;renderSourceResult(result);const regions=Array.isArray(result.preferredRegions)?(result.preferredRegions.join('、')||'仅未标注地区'):'全部地区';const message='来源已保存，采用 '+(result.sourceIps||[]).length+' 个 API IP（'+regions+'）';setStatus($('#sourceStatus'),message);notify(message);}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#sourceStatus'),message,true);notify(message,'error');}finally{sourceBusy=false;updateRegionActionState();}}
async function saveConfig(element,label){try{setStatus(element,label+'中…');await persistConfig();setStatus(element,label+'成功');notify(label+'成功');await loadDns();}catch(error){const message=error instanceof Error?error.message:String(error);setStatus(element,message,true);notify(message,'error');}}
async function loadConfig(rethrow=false){try{Object.assign(state,await api('/api/config'));savedPreferredRegions=normalizeRegionSelection(state.preferredRegions);state.preferredRegions=normalizeRegionSelection(state.preferredRegions);renderConfig();setStatus($('#loginStatus'),'');$('#login').classList.add('hidden');$('#app').classList.remove('hidden');await Promise.all([loadDns(),loadPreferredSnapshot(),loadCronStatus()]);await loadRegionCatalog();}catch(error){const message=error instanceof Error?error.message:String(error);if(message==='未登录'){setStatus($('#loginStatus'),'');$('#password')?.focus();}else if(message.includes('登录已过期'))setStatus($('#loginStatus'),message,true);else setStatus($('#runtimeStatus'),message,true);if(rethrow)throw error;}}
function showPage(page){document.querySelectorAll('.page').forEach(element=>element.classList.toggle('active',element.id===page));document.querySelectorAll('.nav button').forEach(element=>element.classList.toggle('active',element.dataset.page===page));$('#pageTitle').textContent=page==='settings'?'全局设置':'仪表盘';document.body.dataset.page=page;if(page==='dashboard')loadDns();scrollToTop();}
function updateDnsHint(){const hint=$('#dnsRuleHint');if(hint)hint.textContent=$('#dnsType').value==='CNAME'?'CNAME 会同步创建泛 CNAME，并清理两侧同名的 A/AAAA。':'保存后会同步创建或更新对应类型的泛记录；可用类型：A、AAAA、CNAME。';}
function isDnsIpv4(value){const parts=value.split('.');return parts.length===4&&parts.every(part=>/^(0|[1-9]\d*)$/.test(part)&&Number(part)<=255);}
function isDnsIpv6(value){if(!value.includes(':'))return false;const clean=value.split('%',1)[0];if(!/^[0-9a-f:]+$/i.test(clean))return false;const double=clean.indexOf('::');if(double!==-1&&clean.indexOf('::',double+2)!==-1)return false;const groups=clean.split(':').filter(Boolean);if(groups.some(group=>group.length>4))return false;return double!==-1?groups.length<8:groups.length===8;}
function detectDnsType(value){const content=value.trim();return isDnsIpv4(content)?'A':isDnsIpv6(content)?'AAAA':'CNAME';}
function bulkDnsRecordText(record){const line=record.content;return record.editable===false?'# '+line:line;}
async function openBulkDns(){const dialog=$('#bulkDnsDialog'),textarea=$('#bulkDnsContent'),button=$('#bulkDns');if(!dialog||!textarea)return;if(button)setBusy('#bulkDns',true);try{await loadDns();const domain=String(state.defaultDomain||'').trim().toLowerCase().replace(/\.$/,'');const lines=dnsState.records.filter(record=>String(record.name||'').trim().toLowerCase().replace(/\.$/,'')===domain).map(bulkDnsRecordText);textarea.value=lines.length?lines.join('\n')+'\n':'';setStatus($('#bulkDnsLoadStatus'),lines.length?'已加载 '+lines.length+' 条可编辑记录':'当前没有可编辑记录');setStatus($('#bulkDnsStatus'),'');dialog.showModal();}finally{if(button)setBusy('#bulkDns',false);}}
function closeBulkDns(){const dialog=$('#bulkDnsDialog');if(dialog?.open)dialog.close();}
async function copyBulkDns(){const textarea=$('#bulkDnsContent');if(!textarea)return;const value=textarea.value;if(!value){setStatus($('#bulkDnsStatus'),'文本框为空，没有可复制的内容',true);return;}try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value);else{textarea.focus();textarea.select();if(!document.execCommand('copy'))throw Error('复制失败');}setStatus($('#bulkDnsStatus'),'已复制到剪切板');}catch(error){setStatus($('#bulkDnsStatus'),error instanceof Error?error.message:'复制失败，请手动选择文本复制',true);}}
async function pasteBulkDns(){const textarea=$('#bulkDnsContent');if(!textarea)return;try{if(!navigator.clipboard?.readText)throw Error('当前浏览器不支持读取剪切板，请使用 Ctrl+V 粘贴');const value=await navigator.clipboard.readText();if(!value){setStatus($('#bulkDnsStatus'),'剪切板为空',true);return;}textarea.value=value;textarea.selectionStart=textarea.selectionEnd=value.length;setStatus($('#bulkDnsStatus'),'已覆盖粘贴剪切板内容');}catch(error){setStatus($('#bulkDnsStatus'),error instanceof Error?error.message:'粘贴失败，请检查剪切板权限',true);}}
function sortBulkDns(){const textarea=$('#bulkDnsContent');if(!textarea)return;const source=textarea.value,hasTrailingNewline=/\r?\n$/.test(source),lines=source.split(/\r?\n/),records=[],comments=[];lines.forEach((line,index)=>{const value=line.trim();if(!value){return;}if(value.startsWith('#')){comments.push({value,index});return;}const type=detectDnsType(value),rank=type==='A'?0:type==='AAAA'?1:2;records.push({value,type,rank,index});});const ipv4Key=value=>value.split('.').map(part=>String(part).padStart(3,'0')).join('.');records.sort((left,right)=>left.rank-right.rank||(left.rank===0?ipv4Key(left.value).localeCompare(ipv4Key(right.value)):left.value.localeCompare(right.value)));const output=records.map(item=>item.value).concat(comments.map(item=>item.value));textarea.value=output.join('\n')+(hasTrailingNewline&&output.length?'\n':'');setStatus($('#bulkDnsStatus'),records.length?'已按 IPv4、IPv6、目标域名分类排序':'没有可排序的内容');}
function parseBulkDnsText(text){const records=[],errors=[];const domain=String(state.defaultDomain||'').trim().toLowerCase().replace(/\.$/,'');const wildcard='*.'+domain;const syncWildcard=state.domains.find(profile=>profile.id===state.activeDomainId)?.syncWildcard!==false;String(text||'').split(/\r?\n/).forEach((raw,index)=>{const line=raw.trim();if(!line||line.startsWith('#'))return;const columns=line.split(/\s+/);let declaredType='',name='',content='';if(columns.length>=3){declaredType=columns.shift().trim().toUpperCase();name=columns.shift().trim();content=columns.join(' ').trim();}else if(columns.length===2){name=columns[0].trim();content=columns[1].trim();}else{ name=domain;content=line;}if(!name||!content){errors.push('第 '+(index+1)+' 行缺少名称或内容');return;}if(declaredType&&!['A','AAAA','CNAME'].includes(declaredType)){errors.push('第 '+(index+1)+' 行类型仅支持 A、AAAA 或 CNAME');return;}const normalizedName=name.toLowerCase().replace(/\.$/,'');if(syncWildcard&&normalizedName===wildcard)return;if(![domain,...(syncWildcard?[]:[wildcard])].includes(normalizedName)){errors.push('第 '+(index+1)+' 行名称只能是 '+domain+(syncWildcard?'':' 或 '+wildcard));return;}records.push({name:normalizedName,content,type:detectDnsType(content)});});return {records,errors};}
async function saveBulkDns(event){event.preventDefault();const button=$('#saveBulkDns');if(button)button.disabled=true;try{const parsed=parseBulkDnsText($('#bulkDnsContent')?.value||'');if(parsed.errors.length)throw Error(parsed.errors.join('\n'));if(!parsed.records.length&&!await askConfirm('清空 DNS 记录','文本框为空，将删除当前域名全部可编辑 DNS 记录。继续吗？','确认清空',true))return;setStatus($('#bulkDnsStatus'),'正在保存…');const result=await api('/api/dns/records/bulk?domainId='+encodeURIComponent(state.activeDomainId||''),{method:'PUT',body:JSON.stringify({records:parsed.records.map(record=>({name:record.name,content:record.content}))})});closeBulkDns();await loadDns();const summary=result.result||{};const message='批量保存完成：新增 '+(summary.created||0)+'、更新 '+(summary.updated||0)+'、删除 '+(summary.deleted||0)+' 条';setStatus($('#dnsStatus'),message);notify(message);}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#bulkDnsStatus'),message,true);notify(message,'error');}finally{if(button)button.disabled=false;}}
function syncDnsType(){const content=$('#dnsContent').value.trim();if(!content)return;$('#dnsType').value=detectDnsType(content);updateDnsHint();}
function renderDns(){const filter=($('#dnsFilter').value||'').trim().toLowerCase();const records=dnsState.records.filter(record=>[record.type,record.name,record.content].join(' ').toLowerCase().includes(filter));const rows=$('#dnsRows');if(!rows)return;if(!records.length){rows.innerHTML='<tr><td colspan="7" class="empty">'+(filter?'没有匹配的 DNS 记录':'暂无可管理的 DNS 记录')+'</td></tr>';}else{rows.innerHTML=records.map(record=>'<tr><td><span class="badge">'+esc(record.type)+'</span></td><td class="record-name">'+esc(record.name)+'</td><td class="record-content" title="'+esc(record.content)+'">'+esc(record.content)+'</td><td>'+esc(formatTtl(record.ttl))+'</td><td>'+(record.proxied?'橙云':'灰云')+'</td><td>'+(record.comment==='preferred-domain-manager'||(record.tags||[]).includes('preferred-domain-manager')?'<span class="badge managed">优选托管</span>':'<span class="badge">手动</span>')+'</td><td><div class="actions"><button type="button" class="secondary edit-dns" data-id="'+esc(record.id)+'">编辑</button><button type="button" class="danger delete-dns" data-id="'+esc(record.id)+'">删除</button></div></td></tr>').join('');}const count=$('#dnsCount');if(count)count.textContent=String(dnsState.records.length);}
const baseRenderDns=renderDns;renderDns=()=>{baseRenderDns();document.querySelectorAll('#dnsRows tr').forEach(row=>{if(row.cells.length<7)return;const ttl=row.cells[3];const proxy=row.cells[4];ttl.innerHTML='<span class="meta-chip ttl-chip">'+esc(ttl.textContent.trim())+'</span>';const proxied=proxy.textContent.includes('橙');proxy.innerHTML='<span class="meta-chip proxy-chip'+(proxied?' active':'')+'">'+(proxied?'Cloudflare 代理':'仅 DNS')+'</span>';});};
async function loadDns(){if(dnsState.loading)return;if(!state.defaultDomain||!state.cfZoneId||!state.hasCfApiToken){dnsState.records=[];renderDns();setStatus($('#dnsStatus'),'请先保存默认域名、Zone ID 和 API Token');return;}dnsState.loading=true;setBusy('#refreshDns',true);setBusy('#clearDns',true);try{setStatus($('#dnsStatus'),'加载中…');const result=await api('/api/dns/records');dnsState.records=result.records||[];renderDns();setStatus($('#dnsStatus'),'共 '+dnsState.records.length+' 条主域名记录');}catch(error){dnsState.records=[];renderDns();const message=error instanceof Error?error.message:String(error);setStatus($('#dnsStatus'),message,true);notify(message,'error');}finally{dnsState.loading=false;setBusy('#refreshDns',false);const clearButton=$('#clearDns');if(clearButton){clearButton.classList.remove('is-loading');clearButton.setAttribute('aria-busy','false');clearButton.disabled=!clearableDnsRecords().length;}}}
function openDns(record){syncDnsName();dnsState.editingId=record?.id||null;$('#dnsDialogTitle').textContent=record?'编辑 DNS 记录':'新建 DNS 记录';$('#dnsType').value=record?.type||'A';$('#dnsContent').value=record?.content||'';$('#dnsTtl').value='自动 · 60 秒';const ttlLabel=$('#dnsTtl')?.previousElementSibling;if(ttlLabel)ttlLabel.textContent='缓存时间';const proxyLabel=$('#dnsProxied')?.parentElement;if(proxyLabel&&proxyLabel.lastChild)proxyLabel.lastChild.textContent='仅 DNS 解析';setStatus($('#dnsFormStatus'),'');syncDnsType();updateDnsHint();$('#dnsDialog').showModal();setTimeout(()=>$('#dnsContent').focus(),0);}
function closeDns(){const dialog=$('#dnsDialog');if(dialog.open)dialog.close();dnsState.editingId=null;}
function reopenDns(){const dialog=$('#dnsDialog');if(!dialog.open)dialog.showModal();setTimeout(()=>$('#dnsContent').focus(),0);}
function normalizeDnsContent(value){return String(value||'').trim().toLowerCase().replace(/\.$/,'');}
function findDuplicateDnsRecord(type,content,editingId){const normalized=normalizeDnsContent(content);const domain=String(state.defaultDomain||'').toLowerCase();return dnsState.records.find(record=>record.id!==editingId&&String(record.name||'').toLowerCase()===domain&&record.type===type&&normalizeDnsContent(record.content)===normalized);}
async function submitDns(event){event.preventDefault();const button=$('#saveDns');const editing=Boolean(dnsState.editingId);if(button)button.disabled=true;try{const content=$('#dnsContent').value.trim();if(!content)throw Error('记录内容不能为空');const type=detectDnsType(content);$('#dnsType').value=type;updateDnsHint();const duplicate=findDuplicateDnsRecord(type,content,dnsState.editingId);if(duplicate)throw Error('该 '+type+' 记录已经存在：'+duplicate.content+'，无需重复添加。');const sameType=dnsState.records.find(record=>record.id!==dnsState.editingId&&record.name.toLowerCase()===String(state.defaultDomain||'').toLowerCase()&&record.type===type);if(!editing&&type==='CNAME'&&sameType){const dnsDialog=$('#dnsDialog');if(dnsDialog.open)dnsDialog.close();const overwrite=await askConfirm('CNAME 记录已存在','当前域名已有 CNAME 记录：\n'+sameType.content+'\n继续保存会替换它，并同步更新泛 CNAME。','替换保存',true);if(!overwrite){reopenDns();return;}}await api('/api/dns/records'+(editing?'/'+encodeURIComponent(dnsState.editingId):''),{method:editing?'PUT':'POST',body:JSON.stringify({type,name:state.defaultDomain,content,proxied:false})});closeDns();await loadDns();setStatus($('#dnsStatus'),editing?'记录已更新':'记录已创建');notify((editing?'记录已更新为 ':'记录已创建，类型为 ')+type);if(button)button.blur();}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#dnsStatus'),message,true);notify(message,'error');}finally{if(button)button.disabled=false;}}
async function deleteDns(id){const record=dnsState.records.find(item=>item.id===id);if(!record)return;const confirmed=await askConfirm('删除 DNS 记录','确定删除 '+record.type+' '+record.name+' 吗？\n对应泛记录也会同步删除。','删除记录',true);if(!confirmed)return;try{await api('/api/dns/records/'+encodeURIComponent(id),{method:'DELETE'});await loadDns();setStatus($('#dnsStatus'),'记录已删除');notify('记录已删除');}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#dnsStatus'),message,true);notify(message,'error');}}
let actionBusy=false,previewCancelled=false;
async function runPreferredCheck(){if(actionBusy)return;actionBusy=true;previewCancelled=false;setPreferredSnapshot({available:false});setBusy('#preview',true);$('#sync').disabled=true;$('#cancelPreview').classList.remove('hidden');try{let progress=await api('/api/ips/progress'),collected,candidates,batchSize=20,checkedCount=0,reachable=[];if(progress.available){collected=progress.collected;candidates=collected.merged||[];checkedCount=Number(progress.checkedCount)||0;reachable=progress.reachable||[];setStatus($('#status'),'继续上次检测：已完成 '+checkedCount+'/'+candidates.length+' 个');}else{setStatus($('#status'),'正在获取全部候选 IP…');collected=await api('/api/ips/collect',{method:'POST',body:'{}'});candidates=collected.merged||[];batchSize=Math.max(1,Number(collected.batchSize)||20);}if(!candidates.length)throw Error('没有可检测的优选 IP，请先配置优选 API 或手动 IP');renderSourceResult({...collected,checkedCount,skippedCount:candidates.length-checkedCount,reachable});while(checkedCount<candidates.length){if(previewCancelled)throw Error('检测已停止');const number=Math.floor(checkedCount/batchSize)+1,total=Math.ceil(candidates.length/batchSize);setStatus($('#status'),'检测第 '+number+'/'+total+' 批 · 已完成 '+checkedCount+'/'+candidates.length+' 个');const result=await api('/api/ips/check-batch',{method:'POST',body:'{}'});checkedCount=Number(result.checkedCount)||0;reachable=result.reachable||[];const current={...collected,checkedTcp:false,checkedCount,skippedCount:Math.max(0,candidates.length-checkedCount),reachable};renderSourceResult(current);}setStatus($('#status'),'正在保存完整检测结果…');const completed=await api('/api/ips/complete',{method:'POST',body:'{}'});setPreferredSnapshot({available:true,...completed});const message='全部检测完成：'+candidates.length+' 个候选，TCP 443 可用 '+preferredState.collected.reachable.length+' 个';setStatus($('#status'),message);notify(message);}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#status'),message,true);notify(message,previewCancelled?'success':'error');}finally{if(previewCancelled)await api('/api/ips/cancel',{method:'POST',body:'{}'}).catch(()=>{});actionBusy=false;previewCancelled=false;setBusy('#preview',false);$('#cancelPreview').classList.add('hidden');updatePreferredSummary();}}
async function runSyncAction(){if(actionBusy)return;const target=selectedSyncProfile();if(!target){notify('请先选择要同步的域名','error');return;}const targetId=target.id,targetDomain=target.domain;actionBusy=true;['#preview','#sync'].forEach(selector=>setBusy(selector,true));['#dnsDomain','#preferredDomain'].forEach(selector=>{const input=$(selector);if(input)input.disabled=true;});try{setStatus($('#status'),'正在同步 '+targetDomain+'…');const result=await api('/api/sync?domainId='+encodeURIComponent(targetId),{method:'POST',body:'{}'});const message=result.result?.skippedCname?targetDomain+' 检测到 CNAME，已跳过 IP 同步':targetDomain+' 同步完成';setStatus($('#status'),message);notify(message);await loadDns();}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#status'),targetDomain+'：'+message,true);notify(targetDomain+'：'+message,'error');}finally{actionBusy=false;['#preview','#sync'].forEach(selector=>setBusy(selector,false));['#dnsDomain','#preferredDomain'].forEach(selector=>{const input=$(selector);if(input)input.disabled=!state.domains.length;});updatePreferredSummary();}}
async function telegramAction(path,method,label){try{['#telegramTest','#telegramSetWebhook','#telegramDeleteWebhook','#telegramCommands'].forEach(selector=>setBusy(selector,true));setStatus($('#telegramStatus'),label+'中…');await persistConfig();const result=await api(path,{method,body:'{}'});const detail=result.bot?'：'+(result.bot.username?'@'+result.bot.username:(result.bot.first_name||'连接成功')):result.webhookUrl?'：'+result.webhookUrl:'';const message=label+'成功'+detail;setStatus($('#telegramStatus'),message);notify(message);}catch(error){const message=error instanceof Error?error.message:String(error);setStatus($('#telegramStatus'),message,true);notify(message,'error');}finally{['#telegramTest','#telegramSetWebhook','#telegramDeleteWebhook','#telegramCommands'].forEach(selector=>setBusy(selector,false));}}
